function getProducts(){
  try{
    const raw=localStorage.getItem('nyk_products');
    if(raw){const p=JSON.parse(raw);
      if(Array.isArray(p)&&p.length>0)
      return p;}
  }catch(e){}
  localStorage.setItem('nyk_products',JSON.stringify(SEED_PRODUCTS));
  return SEED_PRODUCTS;
}

function getSettings(){
  try{
    const raw=localStorage.getItem('nyk_settings');
    if(raw)return JSON.parse(raw);
  }catch(e){}
  return {
    // googleFormUrl:'https://forms.gle/YOUR_FORM_ID',
    googleFormUrl:'https://forms.gle/tj5J2TQ1wiSG5ya86',
    storeName:'Ntwana Ya Kasi',
    announcement:''
  };
}

