// ========== PRODUCTS ==========
let activeFilter='All';

function renderProducts(filter){
  activeFilter=filter;
  const grid=document.getElementById('productsGrid');
  const prods=getProducts();
  const filtered=filter==='All'?prods:prods.filter(p=>p.tags&&p.tags.includes(filter));
  
  grid.innerHTML='';
  if(!filtered.length){
    grid.innerHTML='<p class="no-products">No products found in this category.</p>';
    return;
  }
  filtered.forEach((p,i)=>{
    const card=document.createElement('div');
    card.className='product-card reveal';
    card.style.transitionDelay=`${i*0.06}s`;
    const badgeClass=p.badge&&p.badge.toLowerCase().includes('new')?'new':'';
    const outHtml=p.inStock?'':'<div class="product-out"><span style="color: red;font-size: 2rem; font-weight:600; background:var(--teal);">OUT OF STOCK</span></div>';
    card.innerHTML=`
      <div class="product-img-wrap">
        <img src="${p.image}" alt="${p.name}" loading="lazy"/>
        ${p.badge?`<span class="product-badge ${badgeClass}">${p.badge}</span>`:''}
        ${outHtml}
      </div>
      <div class="product-info">
        <div class="product-name">${p.name}</div>
        <div class="product-tags-row">${(p.tags||[]).slice(0,3).map(t=>`<span class="ptag">${t}</span>`).join('')}</div>
        <div class="product-bottom">
          <span class="product-price">R ${p.price}</span>
          <button class="product-quick" onclick="openModal(getProductById('${p.id}')); event.stopPropagation();">${p.inStock?'Buy Now':'Sold Out'}</button>
        </div>
      </div>`;
    card.onclick=()=>openModal(p);
    grid.appendChild(card);
  });
  // Re-observe reveals
  document.querySelectorAll('.reveal:not(.visible)').forEach(el=>revealObs.observe(el));
}

function getProductById(id){
  return getProducts().find(p=>p.id===id)||null;
}

function initFilters(){
  document.querySelectorAll('.filter-tab').forEach(btn=>{
    btn.addEventListener('click',()=>{
      document.querySelectorAll('.filter-tab').forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      renderProducts(btn.dataset.filter);
    });
  });
}

// ========== MODAL ==========
function openModal(p){
  if(!p)return;
  const settings=getSettings();
  document.getElementById('modalImg').src=p.image;
  document.getElementById('modalName').textContent=p.name;
  document.getElementById('modalPrice').textContent=`R ${p.price}`;
  document.getElementById('modalDesc').textContent=p.description||'';
  document.getElementById('modalColor').textContent=p.color||'Black';
  document.getElementById('modalTags').textContent=(p.tags||[]).join(', ');
  const badge=document.getElementById('modalBadge');
  badge.textContent=p.badge||'';
  badge.style.display=p.badge?'inline-block':'none';
  
  // Sizes
  const sizeSelect=document.getElementById('sizeSelect');
  if(p.sizes&&p.sizes.length>0){
    sizeSelect.style.display='block';
    sizeSelect.innerHTML='<option value="">Select Size</option>'+p.sizes.map(s=>`<option>${s}</option>`).join('');
  }else{
    sizeSelect.style.display='none';
  }
  
  // Buy button
  const buyBtn=document.getElementById('buyBtn');
  const note=document.getElementById('formNote');
  if(!p.inStock){
    buyBtn.className='btn-buy disabled';
    buyBtn.textContent='Out of Stock';
    note.textContent='This item is currently out of stock. Check back soon!';
  }else{
    buyBtn.className='btn-buy';
    buyBtn.textContent='Order via Google Forms';
    const formUrl=settings.googleFormUrl||'https://forms.gle/YOUR_FORM_ID';
    const prefilledUrl=formUrl.includes('?')
      ?`${formUrl}&product=${encodeURIComponent(p.name)}&price=R${p.price}`
      :`${formUrl}?product=${encodeURIComponent(p.name)}&price=R${p.price}`;
    buyBtn.href=prefilledUrl;
    note.textContent="You'll be redirected to our secure order form. Fill in your details and we'll process your order.";
  }
  
  document.getElementById('modalOverlay').classList.add('open');
  document.body.style.overflow='hidden';
}

document.getElementById('modalClose').onclick=closeModal;
document.getElementById('modalOverlay').onclick=(e)=>{
  if(e.target===e.currentTarget)closeModal();};
document.addEventListener('keydown',(e)=>{
  if(e.key==='Escape')closeModal();});
function closeModal(){
  document.getElementById('modalOverlay').classList.remove('open');
  document.body.style.overflow='';
}

// ========== NAV ==========
window.addEventListener('scroll',()=>{
  const nav=document.getElementById('navbar');
  nav.classList.toggle('scrolled',window.scrollY>60);
  document.getElementById('backTop').classList.toggle('visible',window.scrollY>400);
});

document.getElementById('hamburger').onclick=()=>{
  document.getElementById('mobileNav').classList.add('open');
  document.body.style.overflow='hidden';
};
document.getElementById('mobileClose').onclick=closeMobileNav;
function closeMobileNav(){
  document.getElementById('mobileNav').classList.remove('open');
  document.body.style.overflow='';
}

// ========== REVEAL ==========
const revealObs=new IntersectionObserver((entries)=>{
  entries.forEach((e,i)=>{
    if(e.isIntersecting){
      setTimeout(()=>e.target.classList.add('visible'),i*70);
      revealObs.unobserve(e.target);
    }
  });
},{threshold:0.08,rootMargin:'0px 0px -50px 0px'});
document.querySelectorAll('.reveal').forEach(el=>revealObs.observe(el));

// ========== TOAST ==========
function showToast(msg){
  const t=document.getElementById('toast');
  t.textContent=msg;
  t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),3000);
}
